/* Session-only practice UI; question content comes from the signed-in catalog. */
(function(root){
 'use strict';
 const Q=root.WarPlannerPractice;
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let selectedFaction='',scope='faction',listId='',selectedTypes=Object.keys(Q.modes).filter(type=>type!=='mixed'),savedLists=[],activeListId='',length=10,session=null,bank=null,catalog=null,rules=null,error='';
 const focus=()=>document.querySelector('#practice-title')?.focus({preventScroll:true});
 const refresh=control=>{root.refreshWarPlannerContent?.();if(control){const field=[...document.querySelectorAll('#practice-setup [name]')].find(el=>el.name===control.name&&el.value===control.value);field?.focus({preventScroll:true});}else focus();};
 const normalized=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
 function selectionBank(){const army=scope==='list'?savedLists.find(list=>list.id===listId)?.army||{faction:selectedFaction,name:'Unavailable saved list',units:[]}:null;const faction=army?(catalog.factions||[]).find(f=>normalized(f.name)===normalized(army.faction)||(f.aliases||[]).some(a=>normalized(a)===normalized(army.faction)))?.name||army.faction:selectedFaction;return Q.buildBank({faction,army,rules,units:catalog.units,detachments:catalog.detachments||[]});}
 function readSetup(form){const fd=new FormData(form);if(['list','faction'].includes(fd.get('practice_scope')))scope=String(fd.get('practice_scope'));if(fd.has('practice_faction'))selectedFaction=String(fd.get('practice_faction'));if(fd.has('practice_list'))listId=String(fd.get('practice_list'));selectedTypes=fd.getAll('practice_modes').map(String);length=Number(fd.get('practice_length'));}
 const scopeLabel=()=>session.scope==='list'?session.listName+' · '+session.faction:session.faction;
 function render(context){
  catalog=context.catalog;rules=context.rules;savedLists=Array.isArray(context.savedLists)?context.savedLists:[];activeListId=context.activeListId||'';
  // Only the standalone Aeldari prototype lacks catalog faction metadata.
  if(!catalog.factions){catalog={...catalog,units:catalog.units.map(u=>({...u,faction:u.faction||'Aeldari'}))};rules=rules.map(r=>({...r,faction:r.faction||'Aeldari'}));}
  if(session)return session.index>=session.questions.length?results():question();
  const factions=catalog.factions||[{name:'Aeldari',group:'Xenos'}],order=['Space Marines','Imperium','Chaos','Xenos'];
  if(!factions.some(f=>f.name===selectedFaction))selectedFaction=factions.find(f=>f.name===context.faction)?.name||factions[0]?.name||'';
  if(!savedLists.some(list=>list.id===listId))listId=savedLists.find(list=>list.id===activeListId)?.id||savedLists[0]?.id||'';
  bank=selectionBank();
  const available=selectedTypes.reduce((sum,type)=>sum+(bank.counts[type]||0),0),emptyTypes=selectedTypes.filter(type=>!bank.counts[type]);
  const factionField=`<label>Faction<select name="practice_faction">${[...order,'Other'].map(group=>{const entries=factions.filter(f=>group==='Other'?!order.includes(f.group):f.group===group).sort((a,b)=>a.name.localeCompare(b.name));return entries.length?`<optgroup label="${group}">${entries.map(f=>`<option ${f.name===selectedFaction?'selected':''}>${e(f.name)}</option>`).join('')}</optgroup>`:'';}).join('')}</select></label>`;
  const listField=`<label>Army list<select name="practice_list" ${savedLists.length?'':'disabled'}>${savedLists.length?[...savedLists].sort((a,b)=>a.army.name.localeCompare(b.army.name)).map(list=>`<option value="${e(list.id)}" ${list.id===listId?'selected':''}>${e(list.army.name)} — ${e(list.army.faction)}</option>`).join(''):'<option value="">No saved lists yet</option>'}</select></label>`;
  return `<section class="practice-page"><header class="heading"><div><span class="eyebrow">RECALL PRACTICE</span><h1 id="practice-title" tabindex="-1">Know it by heart.</h1><p>Choose your material and mix the questions you want.</p></div></header><form id="practice-setup" class="practice-setup"><label>Quiz content<select name="practice_scope"><option value="faction" ${scope==='faction'?'selected':''}>Whole faction</option><option value="list" ${scope==='list'?'selected':''} ${savedLists.length?'':'disabled'}>My saved army list</option></select></label>${scope==='list'?listField:factionField}<div class="practice-list-actions"><button type="button" class="outline" data-action="list-library">My saved lists</button><span>Import or create lists in My army.</span></div><fieldset class="practice-type-picker"><legend>Question types</legend><p>Choose one or more.</p><div class="practice-type-options">${Object.entries(Q.modes).filter(([id])=>id!=='mixed').map(([id,label])=>`<label><input type="checkbox" name="practice_modes" value="${id}" ${selectedTypes.includes(id)?'checked':''}><span>${e(label)}<small>${bank.counts[id]} available</small></span></label>`).join('')}</div><div class="practice-type-actions"><button type="button" class="text-button" data-practice-action="all-types">Select all</button><button type="button" class="text-button" data-practice-action="no-types">Clear</button></div></fieldset><label>Questions<select name="practice_length">${[5,10,20].map(n=>`<option ${length===n?'selected':''}>${n}</option>`).join('')}</select></label><p class="practice-note">${scope==='list'?'Units and answers come from your saved list, with rules for its selected detachments and enhancements. Repeated squads count once.':'Questions and all four choices stay within the selected faction.'} Incomplete summaries and unknown stats are skipped. Each question needs four valid choices.</p>${scope==='list'&&bank.unmatchedUnits.length?`<p class="practice-note">Catalog unit data is still needed for: ${e(bank.unmatchedUnits.join(', '))}.</p>`:''}${emptyTypes.length?`<p class="practice-note">No eligible questions for: ${e(emptyTypes.map(type=>Q.modes[type]).join(', '))}. Available selected types will be used.</p>`:''}${available&&available<length?`<p class="practice-note">This set will use the ${available} available questions without repeats.</p>`:''}${!selectedTypes.length?'<p class="practice-note" role="status">Choose at least one question type.</p>':!available?'<p class="practice-note" role="status">There are not enough distinct answers yet. Choose other question types or update your list’s catalog coverage.</p>':''}<p class="practice-error" role="status">${e(error)}</p><button type="submit" class="primary" ${available&&selectedTypes.length?'':'disabled'}>Start practice <span aria-hidden="true">→</span></button></form></section>`;
 }

 function explanation(q){if(q.review&&root.WarPlannerStudyCards)return '<div class="practice-explanation">'+root.WarPlannerStudyCards.reviewCard(q.review,{sources:root.WarPlanLessons?.sources||{}})+'</div>';return `<div class="practice-explanation"><p>${e(q.explanation.summary)}</p>${q.explanation.conditions.length?`<ul>${q.explanation.conditions.map(c=>`<li>${e(c)}</li>`).join('')}</ul>`:''}<small>${e(q.explanation.sourceLabel)}${q.explanation.sourceUrl?` · <a href="${e(q.explanation.sourceUrl)}" target="_blank" rel="noopener noreferrer">Source</a>`:''}</small></div>`;}
 function question(){
  const q=session.questions[session.index],answer=session.answers[session.index],correct=q.options.find(o=>o.id===q.correct),score=session.answers.filter(a=>a.correct).length;
  return `<section class="practice-page"><div class="practice-top"><span>${e(scopeLabel())} · ${session.types.length>1?'Custom mix':e(Q.modes[session.mode])}</span><button type="button" class="outline practice-reset-button" data-practice-action="reset">New practice set</button></div><div class="practice-progress"><span>Question ${session.index+1} of ${session.questions.length}</span><span>${score} correct / ${session.answers.length} answered</span></div><article class="practice-card"><span class="rule-badge rule-${e(q.category)}">${e(Q.categories[q.category]||'Unit stat')}</span><h1 id="practice-title" tabindex="-1">${e(q.prompt)}</h1><p class="practice-clue">${e(q.clue)}</p><div class="practice-options" aria-label="Answer choices">${q.options.map((option,i)=>`<button type="button" class="practice-option ${answer?(option.id===q.correct?'practice-correct':option.id===answer.id?'practice-incorrect':''):''}" data-practice-answer="${e(option.id)}" ${answer?'disabled':''}><span aria-hidden="true">${'ABCD'[i]}</span><span>${e(option.label)}</span>${answer&&(option.id===q.correct||option.id===answer.id)?`<strong>${option.id===q.correct?'✓ Correct':'× Your answer'}</strong>`:''}</button>`).join('')}</div>${answer?`<div class="practice-feedback"><p role="status"><strong>${answer.correct?'Correct.':'The correct answer is '+e(correct.label)+'.'}</strong></p>${explanation(q)}</div><button type="button" class="primary practice-next" data-practice-action="next">${session.index+1===session.questions.length?'See results':'Next question'} <span aria-hidden="true">→</span></button><div class="practice-report-container" data-report-container>${root.WarPlannerReports?.practiceForQuestion(q)||''}</div>`:''}</article></section>`;
 }
 function results(){const score=session.answers.filter(a=>a.correct).length,missed=session.questions.filter((_q,i)=>!session.answers[i].correct);return `<section class="practice-page"><header class="heading"><div><span class="eyebrow">SET COMPLETE · ${e(scopeLabel())}</span><h1 id="practice-title" tabindex="-1">${score} of ${session.questions.length} correct</h1><p>${missed.length?'Revisit the ones that need another look.':'Every answer correct. Try a new set to keep practising.'}</p></div></header><div class="button-row"><button type="button" class="primary" data-practice-action="again">Another set</button><button type="button" class="outline" data-practice-action="reset">Change practice</button></div>${missed.length?`<details class="practice-review"><summary>Review missed questions (${missed.length})</summary>${missed.map(q=>`<article><h2>${e(q.prompt)}</h2><p>${e(q.clue)}</p><strong>${e(q.options.find(o=>o.id===q.correct).label)}</strong>${explanation(q)}</article>`).join('')}</details>`:''}<p class="practice-note">This score is for this set only.</p></section>`;}
 function start(form=null){try{if(form)readSetup(form);bank=selectionBank();session=Q.createSession(bank,{types:selectedTypes,count:length});if(!session.questions.length){session=null;error='There are not enough distinct answers. Choose other question types or a different list.';}else error='';}catch(failure){session=null;error=failure.message;}refresh();}
 document.addEventListener('change',event=>{const form=event.target.closest?.('#practice-setup');if(!form)return;const control={name:event.target.name,value:event.target.value};readSetup(form);error='';refresh(control);});
 document.addEventListener('submit',event=>{if(event.target.id!=='practice-setup')return;event.preventDefault();start(event.target);});
 document.addEventListener('click',event=>{const b=event.target.closest?.('[data-practice-answer],[data-practice-action]');if(!b)return;if(b.dataset.practiceAnswer!==undefined){if(session&&Q.answer(session,b.dataset.practiceAnswer))refresh();return;}const action=b.dataset.practiceAction;if(action==='all-types'||action==='no-types'){selectedTypes=action==='all-types'?Object.keys(Q.modes).filter(type=>type!=='mixed'):[];error='';refresh();}if(action==='reset'){session=null;error='';refresh();}if(action==='next'&&session?.answers.length===session.index+1){session.index++;refresh();}if(action==='again'&&session)start();});
 root.WarPlannerPracticePage={render,reset(){selectedFaction='';scope='faction';listId='';selectedTypes=Object.keys(Q.modes).filter(type=>type!=='mixed');savedLists=[];activeListId='';length=10;session=null;bank=null;catalog=null;rules=null;error='';}};
})(window);
